CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TYPE public.license_type AS ENUM ('trial', 'paid', 'custom');
CREATE TYPE public.license_state AS ENUM ('active', 'revoked');
CREATE TYPE public.audit_action AS ENUM ('license_created', 'license_activated', 'license_revoked', 'license_reactivated', 'license_extended', 'device_reset', 'customer_updated', 'license_archived', 'license_deactivated');
CREATE TABLE public.admin_profiles (id uuid PRIMARY KEY, display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.admin_profiles TO authenticated; GRANT ALL ON public.admin_profiles TO service_role; ALTER TABLE public.admin_profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE POLICY "Administrators can read profiles" ON public.admin_profiles FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Users can create own profile" ON public.admin_profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY "Administrators can update profiles" ON public.admin_profiles FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Users can read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.claim_first_admin(_display_name text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _uid uuid := auth.uid(); BEGIN IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF char_length(trim(_display_name)) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid display name'; END IF; PERFORM pg_advisory_xact_lock(73421001); IF EXISTS (SELECT 1 FROM public.user_roles) THEN RETURN public.has_role(_uid, 'admin'); END IF; INSERT INTO public.admin_profiles (id, display_name) VALUES (_uid, trim(_display_name)) ON CONFLICT (id) DO UPDATE SET display_name = EXCLUDED.display_name, updated_at = now(); INSERT INTO public.user_roles (user_id, role) VALUES (_uid, 'admin') ON CONFLICT DO NOTHING; RETURN true; END; $$;
GRANT EXECUTE ON FUNCTION public.claim_first_admin(text) TO authenticated;
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), identifier text NOT NULL UNIQUE CHECK (identifier ~ '^[a-z0-9][a-z0-9._-]{2,63}$'), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Administrators can read products" ON public.products FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 160), phone text, email text, handle text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.customers TO authenticated; GRANT ALL ON public.customers TO service_role; ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Administrators manage customers" ON public.customers FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.licenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id), customer_id uuid NOT NULL REFERENCES public.customers(id), key_hash text NOT NULL UNIQUE CHECK (char_length(key_hash) = 64), key_ciphertext text NOT NULL, key_preview text NOT NULL, license_type public.license_type NOT NULL, state public.license_state NOT NULL DEFAULT 'active', duration_seconds bigint NOT NULL CHECK (duration_seconds > 0), created_at timestamptz NOT NULL DEFAULT now(), activated_at timestamptz, expires_at timestamptz, revoked_at timestamptz, archived_at timestamptz, amount_paid numeric(12,2) CHECK (amount_paid IS NULL OR amount_paid >= 0), payment_reference text, notes text, created_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.licenses TO authenticated; GRANT ALL ON public.licenses TO service_role; ALTER TABLE public.licenses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Administrators manage licenses" ON public.licenses FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.license_activations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), license_id uuid NOT NULL REFERENCES public.licenses(id) ON DELETE CASCADE, device_hash text NOT NULL, product_identifier text NOT NULL, activated_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), deactivated_at timestamptz, UNIQUE (license_id, device_hash));
GRANT SELECT, INSERT, UPDATE ON public.license_activations TO authenticated; GRANT ALL ON public.license_activations TO service_role; ALTER TABLE public.license_activations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Administrators manage activations" ON public.license_activations FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), administrator_id uuid, action public.audit_action NOT NULL, license_id uuid REFERENCES public.licenses(id), before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Administrators read audit logs" ON public.audit_logs FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.validation_rate_limits (bucket_key text NOT NULL, window_start timestamptz NOT NULL, attempt_count integer NOT NULL DEFAULT 1 CHECK (attempt_count > 0), PRIMARY KEY (bucket_key, window_start));
GRANT ALL ON public.validation_rate_limits TO service_role; ALTER TABLE public.validation_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE INDEX customers_name_idx ON public.customers (lower(name)); CREATE INDEX customers_email_idx ON public.customers (lower(email)); CREATE INDEX customers_phone_idx ON public.customers (phone); CREATE INDEX licenses_state_idx ON public.licenses (state); CREATE INDEX licenses_expires_at_idx ON public.licenses (expires_at); CREATE INDEX licenses_created_at_idx ON public.licenses (created_at DESC); CREATE INDEX licenses_customer_idx ON public.licenses (customer_id); CREATE INDEX licenses_archived_idx ON public.licenses (archived_at); CREATE INDEX activations_license_active_idx ON public.license_activations (license_id) WHERE deactivated_at IS NULL; CREATE INDEX audit_license_created_idx ON public.audit_logs (license_id, created_at DESC);
CREATE OR REPLACE FUNCTION public.admin_create_license(_product_identifier text, _customer_name text, _phone text, _email text, _handle text, _customer_notes text, _key_hash text, _key_ciphertext text, _key_preview text, _license_type public.license_type, _duration_seconds bigint, _amount_paid numeric, _payment_reference text, _license_notes text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _uid uuid := auth.uid(); _customer_id uuid; _license_id uuid; BEGIN IF NOT public.has_role(_uid, 'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _duration_seconds <= 0 THEN RAISE EXCEPTION 'Duration must be positive'; END IF; INSERT INTO public.customers(name, phone, email, handle, notes) VALUES(trim(_customer_name), nullif(trim(_phone), ''), nullif(lower(trim(_email)), ''), nullif(trim(_handle), ''), nullif(trim(_customer_notes), '')) RETURNING id INTO _customer_id; INSERT INTO public.licenses(product_id, customer_id, key_hash, key_ciphertext, key_preview, license_type, duration_seconds, amount_paid, payment_reference, notes, created_by) SELECT id, _customer_id, _key_hash, _key_ciphertext, _key_preview, _license_type, _duration_seconds, _amount_paid, nullif(trim(_payment_reference), ''), nullif(trim(_license_notes), ''), _uid FROM public.products WHERE identifier = _product_identifier RETURNING id INTO _license_id; IF _license_id IS NULL THEN RAISE EXCEPTION 'Unknown product'; END IF; INSERT INTO public.audit_logs(administrator_id, action, license_id, after_data) VALUES(_uid, 'license_created', _license_id, jsonb_build_object('license_type', _license_type, 'duration_seconds', _duration_seconds, 'customer_id', _customer_id)); RETURN _license_id; END; $$;
GRANT EXECUTE ON FUNCTION public.admin_create_license(text,text,text,text,text,text,text,text,text,public.license_type,bigint,numeric,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_license_action(_license_id uuid, _action text, _seconds bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _uid uuid := auth.uid(); _before public.licenses%ROWTYPE; _new_expiry timestamptz; _audit public.audit_action; BEGIN IF NOT public.has_role(_uid, 'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO _before FROM public.licenses WHERE id = _license_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'License not found'; END IF; IF _action = 'extend' THEN IF _seconds IS NULL OR _seconds <= 0 THEN RAISE EXCEPTION 'Duration must be positive'; END IF; _new_expiry := greatest(coalesce(_before.expires_at, now()), now()) + make_interval(secs => _seconds::double precision); UPDATE public.licenses SET expires_at = _new_expiry, duration_seconds = duration_seconds + _seconds, updated_at = now() WHERE id = _license_id; _audit := 'license_extended'; ELSIF _action = 'revoke' THEN UPDATE public.licenses SET state = 'revoked', revoked_at = now(), updated_at = now() WHERE id = _license_id; _audit := 'license_revoked'; ELSIF _action = 'reactivate' THEN UPDATE public.licenses SET state = 'active', revoked_at = NULL, updated_at = now() WHERE id = _license_id; _audit := 'license_reactivated'; ELSIF _action = 'reset_device' THEN UPDATE public.license_activations SET deactivated_at = now() WHERE license_id = _license_id AND deactivated_at IS NULL; UPDATE public.licenses SET updated_at = now() WHERE id = _license_id; _audit := 'device_reset'; ELSIF _action = 'archive' THEN UPDATE public.licenses SET archived_at = now(), updated_at = now() WHERE id = _license_id; _audit := 'license_archived'; ELSE RAISE EXCEPTION 'Unsupported action'; END IF; INSERT INTO public.audit_logs(administrator_id, action, license_id, before_data, after_data) SELECT _uid, _audit, _license_id, jsonb_build_object('state', _before.state, 'expires_at', _before.expires_at, 'archived_at', _before.archived_at), jsonb_build_object('action', _action, 'expires_at', _new_expiry, 'at', now()); RETURN jsonb_build_object('id', _license_id, 'action', _action, 'expires_at', _new_expiry); END; $$;
GRANT EXECUTE ON FUNCTION public.admin_license_action(uuid,text,bigint) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_update_customer(_license_id uuid, _name text, _phone text, _email text, _handle text, _notes text, _amount_paid numeric, _payment_reference text, _license_notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _uid uuid := auth.uid(); _customer_id uuid; _before jsonb; BEGIN IF NOT public.has_role(_uid, 'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT customer_id INTO _customer_id FROM public.licenses WHERE id = _license_id; IF _customer_id IS NULL THEN RAISE EXCEPTION 'License not found'; END IF; SELECT jsonb_build_object('name', name, 'phone', phone, 'email', email, 'handle', handle) INTO _before FROM public.customers WHERE id = _customer_id; UPDATE public.customers SET name = trim(_name), phone = nullif(trim(_phone), ''), email = nullif(lower(trim(_email)), ''), handle = nullif(trim(_handle), ''), notes = nullif(trim(_notes), ''), updated_at = now() WHERE id = _customer_id; UPDATE public.licenses SET amount_paid = _amount_paid, payment_reference = nullif(trim(_payment_reference), ''), notes = nullif(trim(_license_notes), ''), updated_at = now() WHERE id = _license_id; INSERT INTO public.audit_logs(administrator_id, action, license_id, before_data, after_data) SELECT _uid, 'customer_updated', _license_id, _before, jsonb_build_object('name', _name, 'phone', _phone, 'email', _email, 'handle', _handle); END; $$;
GRANT EXECUTE ON FUNCTION public.admin_update_customer(uuid,text,text,text,text,text,numeric,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.public_license_operation(_operation text, _key_hash text, _product_identifier text, _device_hash text, _bucket_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _window timestamptz := date_trunc('minute', now()); _attempts integer; _license public.licenses%ROWTYPE; _active_device text; _status text; _valid boolean := false; BEGIN INSERT INTO public.validation_rate_limits(bucket_key, window_start, attempt_count) VALUES(_bucket_key, _window, 1) ON CONFLICT(bucket_key, window_start) DO UPDATE SET attempt_count = public.validation_rate_limits.attempt_count + 1 RETURNING attempt_count INTO _attempts; IF _attempts > 30 THEN RETURN jsonb_build_object('valid', false, 'status', 'rate_limited'); END IF; SELECT l.* INTO _license FROM public.licenses l JOIN public.products p ON p.id = l.product_id WHERE l.key_hash = _key_hash AND p.identifier = _product_identifier AND l.archived_at IS NULL; IF NOT FOUND THEN RETURN jsonb_build_object('valid', false, 'status', 'invalid'); END IF; IF _license.state = 'revoked' THEN RETURN jsonb_build_object('valid', false, 'status', 'revoked'); END IF; IF _license.expires_at IS NOT NULL AND _license.expires_at <= now() THEN RETURN jsonb_build_object('valid', false, 'status', 'expired', 'expiresAt', _license.expires_at); END IF; SELECT device_hash INTO _active_device FROM public.license_activations WHERE license_id = _license.id AND deactivated_at IS NULL ORDER BY activated_at DESC LIMIT 1; IF _operation = 'activate' THEN IF _active_device IS NOT NULL AND _active_device <> _device_hash THEN RETURN jsonb_build_object('valid', false, 'status', 'device_mismatch'); END IF; IF _license.activated_at IS NULL THEN UPDATE public.licenses SET activated_at = now(), expires_at = now() + make_interval(secs => duration_seconds::double precision), updated_at = now() WHERE id = _license.id RETURNING * INTO _license; INSERT INTO public.audit_logs(action, license_id, after_data) VALUES('license_activated', _license.id, jsonb_build_object('expires_at', _license.expires_at)); END IF; INSERT INTO public.license_activations(license_id, device_hash, product_identifier) VALUES(_license.id, _device_hash, _product_identifier) ON CONFLICT(license_id, device_hash) DO UPDATE SET last_seen_at = now(), deactivated_at = NULL; _valid := true; _status := 'active'; ELSIF _operation = 'check' THEN IF _active_device IS NULL OR _active_device <> _device_hash THEN RETURN jsonb_build_object('valid', false, 'status', 'device_mismatch'); END IF; UPDATE public.license_activations SET last_seen_at = now() WHERE license_id = _license.id AND device_hash = _device_hash; _valid := true; _status := 'active'; ELSIF _operation = 'deactivate' THEN IF _active_device IS NULL OR _active_device <> _device_hash THEN RETURN jsonb_build_object('valid', false, 'status', 'device_mismatch'); END IF; UPDATE public.license_activations SET deactivated_at = now() WHERE license_id = _license.id AND device_hash = _device_hash AND deactivated_at IS NULL; INSERT INTO public.audit_logs(action, license_id, after_data) VALUES('license_deactivated', _license.id, jsonb_build_object('at', now())); _status := 'deactivated'; ELSE RETURN jsonb_build_object('valid', false, 'status', 'invalid_operation'); END IF; RETURN jsonb_build_object('valid', _valid, 'status', _status, 'expiresAt', _license.expires_at); END; $$;
REVOKE ALL ON FUNCTION public.public_license_operation(text,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_license_operation(text,text,text,text,text) TO anon, authenticated, service_role;